lines=open('/tmp/logo.gray').read().splitlines(); w,h=map(int,lines[0].split()); vals=[[int(float(v)) for v in line.split()] for line in lines[1:]]
chars="   ...',;:clodxkO0KXNWM"; target=['Ok0O0','kdK0O']
def ch(l): return chars[min(len(chars)-1,int(l*len(chars)/256))]
def avg(x0,x1,y0,y1):
 x0=max(0,min(w,x0)); x1=max(x0+1,min(w,x1)); y0=max(0,min(h,y0)); y1=max(y0+1,min(h,y1));
 a=[vals[yy][xx] for yy in range(y0,y1) for xx in range(x0,x1)]
 return sum(a)/len(a)
schemes=[]
# floor boundaries, ceil end, fixed skip, center-ish offsets
for xs in ['floor','fixed','round']:
 for ys in ['floor','fixed','round']:
  out=[]; dif=0; av=[]
  for y in range(2):
   row=''; avrow=[]
   for x in range(5):
    if xs=='floor': x0=x*w//5; x1=(x+1)*w//5
    elif xs=='fixed': x0=x*(w//5); x1=x0+(w//5)
    else: x0=round(x*w/5); x1=round((x+1)*w/5)
    if ys=='floor': y0=y*h//2; y1=(y+1)*h//2
    elif ys=='fixed': y0=y*(h//2); y1=y0+(h//2)
    else: y0=round(y*h/2); y1=round((y+1)*h/2)
    lum=avg(x0,x1,y0,y1); avrow.append(lum); c=ch(lum); row+=c
    if c!=target[y][x]: dif+=1
