set -euo pipefail
cd "$(dirname "$0")"
go build -trimpath -ldflags='-s -w' -o executable .
EOF
chmod +x compile.sh
cat > .gitignore <<'EOF'
/executable
*.o
*.a
*.so
*.dylib
*.dll
*.exe
*.test
*.out
core
core.*
EOF
./compile.sh
./executable --version >/tmp/newv.out 2>/tmp/newv.err; cat /tmp/newv.err"}

