      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.
      --html-title=...  Set HTML output title
  -i, --invert      Invert output image.  Use if your display has a dark
                    background.
      --background=dark   These are just mnemonics whether to use --invert
      --background=light  or not.  If your console has light characters on
                    a dark background, use --background=dark.
      --output=...  Write output to file.
      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.
      --size=WxH    Set output width and height.
  -v, --verbose     Verbose output.
  -V, --version     Print program version.
      --width=N     Set output width, calculate height from ratio.

  The default mode is ` + "`" + `jp2a --term-fit --background=dark'.
  See the man-page for jp2a for more detailed help text.

Project homepage on https://github.com/cslarsen/jp2a
Report bugs to <csl@csl.name>
`

const defaultPalette = "   ...',;:clodxkO0KXNWM"

type dimMode int
const (
    dimDefault dimMode = iota
    dimSize
    dimWidth
    dimHeight
    dimBothWH
)

type termMode int
const (
    termNone termMode = iota
    termFit
    termWidth
    termHeight
    termZoom
)

type options struct {
    palette string
    invert bool
    border bool
    colors bool
    grayscale bool
    fill bool
    flipX bool
    flipY bool
    clear bool
    debug bool
    verbose bool
    html bool
    htmlRaw bool
    htmlNoBold bool
    htmlFontSize int
    htmlTitle string
    output string
    red, green, blue float64
    width, height int
    dmode dimMode
    tmode termMode
    files []string
}

type cell struct { r,g,b,lum float64; ch rune }

type decoded struct { name string; data []byte; img image.Image; width, height, comps int }

func main() {
    os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
    opt := options{palette: defaultPalette, htmlFontSize: 8, htmlTitle: "jp2a converted image", red:0.2989, green:0.5866, blue:0.1145, tmode:termNone}
    if len(args)==0 {
        fmt.Fprint(os.Stderr, "No files specified.\n\n")
        fmt.Fprint(os.Stderr, helpText)
        return 1
    }
    for _, a := range args {
        if a == "-" { opt.files = append(opt.files, a); continue }
        if strings.HasPrefix(a, "-") {
            if !parseOption(a, &opt) {
                fmt.Fprintf(os.Stderr, "Unknown option %s\n\n", a)
                fmt.Fprint(os.Stderr, helpText)
                return 1
            }
            if a == "--help" || a == "-h" { fmt.Fprint(os.Stderr, helpText); return 0 }
            if a == "--version" || a == "-V" { fmt.Fprint(os.Stderr, versionText); return 0 }
        } else {
            opt.files = append(opt.files, a)
        }
    }
    if len(opt.files)==0 {
        fmt.Fprint(os.Stderr, "No files specified.\n\n")
        fmt.Fprint(os.Stderr, helpText)
        return 1
    }
    needsTerm := opt.tmode != termNone || opt.dmode == dimDefault || (opt.dmode == dimWidth && opt.width == 0)
    termCols, termRows := 0,0
    if needsTerm {
        var err error
        termCols, termRows, err = terminalSize()
        if err != nil { fmt.Fprint(os.Stderr, "Environment variable TERM not set.\n"); return 1 }
    }
    // These validations happen after terminal initialization in the original.
    if len([]rune(opt.palette)) < 2 { fmt.Fprint(os.Stderr, "You must specify at least two characters in --chars.\n"); return 1 }
    if math.Abs((opt.red+opt.green+opt.blue)-1.0) > 0.000001 { fmt.Fprint(os.Stderr, "Weights RED + GREEN + BLUE must equal 1.0\n"); return 1 }
    if opt.output != "" && opt.output != "-" {
        f, err := os.Create(opt.output)
        if err != nil { fmt.Fprintf(os.Stderr, "Could not open '%s' for writing.\n", opt.output); return 1 }
        defer f.Close()
        return processAll(&opt, f, termCols, termRows)
    }
    return processAll(&opt, os.Stdout, termCols, termRows)
}

func processAll(opt *options, out io.Writer, termCols, termRows int) int {
    for _, name := range opt.files {
        dec, err := loadImage(name)
        if err != nil { fmt.Fprint(os.Stderr, err.Error()); if !strings.HasSuffix(err.Error(), "\n") { fmt.Fprintln(os.Stderr) }; return 1 }
        ow, oh, derr := outputDimensions(opt, dec.width, dec.height, termCols, termRows)
        if derr != nil { fmt.Fprint(os.Stderr, derr.Error()); return 1 }
        if opt.verbose { verboseInfo(opt, dec, ow, oh) }
        if opt.clear { fmt.Fprint(out, "\033[2J\033[0;0H") }
        renderOne(opt, dec.img, ow, oh, out)
    }
    return 0
}

func parseOption(a string, opt *options) bool {
    switch a {
    case "--help", "-h", "--version", "-V": return true
    case "-b", "--border": opt.border=true; return true
    case "-i", "--invert": opt.invert=true; return true
    case "-x", "--flipx": opt.flipX=true; return true
    case "-y", "--flipy": opt.flipY=true; return true
    case "-f", "--term-fit": opt.tmode=termFit; return true
    case "--term-width": opt.tmode=termWidth; return true
    case "--term-height": opt.tmode=termHeight; return true
    case "-z", "--term-zoom": opt.tmode=termZoom; return true
    case "--colors", "--color": opt.colors=true; return true
    case "--grayscale": opt.grayscale=true; opt.colors=true; return true
    case "--fill": opt.fill=true; return true
    case "--html-fill": opt.fill=true; fmt.Fprint(os.Stderr, "warning: --html-fill has changed to --fill\n"); return true
    case "--html": opt.html=true; return true
    case "--html-raw": opt.htmlRaw=true; return true
    case "--html-no-bold": opt.htmlNoBold=true; return true
    case "--clear": opt.clear=true; return true
    case "-d", "--debug": opt.debug=true; return true
    case "-v", "--verbose": opt.verbose=true; return true
    }
    if strings.HasPrefix(a, "--chars=") { opt.palette = strings.TrimPrefix(a, "--chars="); return true }
    if a == "--background=dark" { opt.invert=false; return true }
    if a == "--background=light" { opt.invert=true; return true }
    if strings.HasPrefix(a, "--output=") { opt.output = strings.TrimPrefix(a, "--output="); return true }
    if strings.HasPrefix(a, "--html-title=") { opt.htmlTitle = strings.TrimPrefix(a, "--html-title="); return true }
    if strings.HasPrefix(a, "--html-fontsize=") { n, ok := parseIntPrefix(strings.TrimPrefix(a,"--html-fontsize=")); if !ok { return false }; opt.htmlFontSize=n; return true }
    if strings.HasPrefix(a, "--width=") { n, ok := parseIntPrefix(strings.TrimPrefix(a,"--width=")); if !ok { return false }; if n<0 { opt.width=n; opt.dmode=dimWidth; return true }; opt.width=n; if opt.dmode==dimHeight || opt.dmode==dimBothWH { opt.dmode=dimBothWH } else { opt.dmode=dimWidth }; return true }
    if strings.HasPrefix(a, "--height=") { n, ok := parseIntPrefix(strings.TrimPrefix(a,"--height=")); if !ok { return false }; opt.height=n; if opt.dmode==dimWidth || opt.dmode==dimBothWH { opt.dmode=dimBothWH } else { opt.dmode=dimHeight }; return true }
    if strings.HasPrefix(a, "--size=") { w,h,ok := parseSize(strings.TrimPrefix(a,"--size=")); if !ok { return false }; opt.width=w; opt.height=h; opt.dmode=dimSize; return true }
    if strings.HasPrefix(a, "--red=") { f,ok:=parseFloatPrefix(strings.TrimPrefix(a,"--red=")); if !ok {return false}; opt.red=f; return true }
    if strings.HasPrefix(a, "--green=") { f,ok:=parseFloatPrefix(strings.TrimPrefix(a,"--green=")); if !ok {return false}; opt.green=f; return true }
    if strings.HasPrefix(a, "--blue=") { f,ok:=parseFloatPrefix(strings.TrimPrefix(a,"--blue=")); if !ok {return false}; opt.blue=f; return true }
    return false
}

func parseIntPrefix(s string) (int,bool) {
    if s=="" { return 0,false }
    i:=0
    if s[i]=='+' || s[i]=='-' { i++ }
    start:=i
    for i<len(s) && s[i]>='0' && s[i]<='9' { i++ }
    if i==start { return 0,false }
    n,err:=strconv.Atoi(s[:i]); if err!=nil { return 0,false }
    return n,true
}
func parseFloatPrefix(s string) (float64,bool) {
    if s=="" { return 0,false }
    best:=""
    for i:=1;i<=len(s);i++ { if _,err:=strconv.ParseFloat(s[:i],64); err==nil { best=s[:i] } }
    if best=="" { return 0,false }
    f,err:=strconv.ParseFloat(best,64); if err!=nil { return 0,false }
    return f,true
}
func parseSize(s string) (int,int,bool) {
    w, ok := parseIntPrefix(s); if !ok { return 0,0,false }
    i:=0; if s[i]=='+'||s[i]=='-' { i++ }; for i<len(s)&&s[i]>='0'&&s[i]<='9'{i++}
    if i>=len(s) || s[i]!='x' { return 0,0,false }
    h, ok := parseIntPrefix(s[i+1:]); if !ok { return 0,0,false }
    return w,h,true
}

func terminalSize() (int,int,error) {
    if os.Getenv("TERM") == "" { return 0,0,errors.New("no term") }
    cols, rows := 80, 24
    if v:=os.Getenv("COLUMNS"); v!="" { if n,err:=strconv.Atoi(v); err==nil && n>0 { cols=n } }
    if v:=os.Getenv("LINES"); v!="" { if n,err:=strconv.Atoi(v); err==nil && n>0 { rows=n } }
    return cols, rows, nil
}

func outputDimensions(opt *options, sw, sh, termCols, termRows int) (int,int,error) {
    if sw<=0 || sh<=0 { return 0,0,fmt.Errorf("Invalid width or height specified\n") }
    termH := termRows-1
    if termH < 1 { termH = 1 }
    borderExtra := 0
    if opt.border { borderExtra = 2 }
    if opt.tmode != termNone || opt.dmode == dimDefault {
        mode := opt.tmode
        if mode==termNone { mode=termFit }
        availW := termCols - borderExtra
        availH := termH - borderExtra
        if availW < 0 { availW=0 }; if availH<0 { availH=0 }
        switch mode {
        case termWidth:
            ow := availW; oh := int(math.Round(float64(ow)*float64(sh)/float64(sw)/2.0)); if oh<1{oh=1}; return ow,oh,nil
        case termHeight:
            oh := availH; ow := int(math.Round(float64(oh)*float64(sw)/float64(sh)*2.0)); if ow<1{ow=1}; return ow,oh,nil
        case termZoom:
            return availW, availH, nil
        default:
            owW := availW; ohW := int(math.Round(float64(owW)*float64(sh)/float64(sw)/2.0)); if ohW<1{ohW=1}
            ohH := availH; owH := int(math.Round(float64(ohH)*float64(sw)/float64(sh)*2.0)); if owH<1{owH=1}
            if ohW <= availH { return owW, ohW, nil }
            return owH, ohH, nil
        }
    }
    switch opt.dmode {
    case dimSize:
        if opt.width<=0 || opt.height<=0 { return 0,0,fmt.Errorf("Invalid width or height specified\n") }
        return opt.width,opt.height,nil
    case dimBothWH:
        if opt.width<0 || opt.height<=0 { return 0,0,fmt.Errorf("Invalid width or height specified\n") }
        return opt.width,opt.height,nil
    case dimWidth:
        if opt.width<0 { return 0,0,fmt.Errorf("Invalid width or height specified\n") }
        if opt.width==0 { return 0, termH, nil }
        ow:=opt.width; if ow<2{ow=2}
        oh:=int(math.Round(float64(ow)*float64(sh)/float64(sw)/2.0)); if oh<1{oh=1}
        return ow,oh,nil
    case dimHeight:
        if opt.height<=0 { return 0,0,fmt.Errorf("Invalid width or height specified\n") }
        oh:=opt.height
        ow:=int(math.Round(float64(oh)*float64(sw)/float64(sh)*2.0)); if ow<1{ow=1}
        return ow,oh,nil
    }
    return 0,0,fmt.Errorf("Invalid width or height specified\n")
}

func loadImage(name string) (*decoded,error) {
    var data []byte
    var err error
    display := name
    if name == "-" { display = "<stdin>"; data,err = io.ReadAll(os.Stdin) } else if strings.HasPrefix(name,"file://") { path:=strings.TrimPrefix(name,"file://"); data,err=os.ReadFile(path) } else if strings.HasPrefix(name,"http://") || strings.HasPrefix(name,"https://") {
        client:=http.Client{Timeout:30*time.Second}; resp,e:=client.Get(name); if e!=nil { return nil,fmt.Errorf("%s\n", e.Error()) }; defer resp.Body.Close(); data,err=io.ReadAll(resp.Body)
    } else { data,err=os.ReadFile(name) }
    if err!=nil { return nil,fmt.Errorf("Can't open %s\n", name) }
    if len(data)==0 { return nil,fmt.Errorf("Empty input file\n") }
    if len(data)<2 { b0:=data[0]; return nil,fmt.Errorf("Premature end of JPEG file\nNot a JPEG file: starts with 0x%02x 0x%02x\n", b0,b0) }
    if !(data[0]==0xff && data[1]==0xd8) { return nil,fmt.Errorf("Not a JPEG file: starts with 0x%02x 0x%02x\n", data[0],data[1]) }
    img,_,e:=image.Decode(bytes.NewReader(data)); if e!=nil { return nil,fmt.Errorf("JPEG datastream contains no image\n") }
    b:=img.Bounds(); comps:=jpegComponents(data); if comps==0 { comps=3 }
    return &decoded{name:display,data:data,img:img,width:b.Dx(),height:b.Dy(),comps:comps},nil
}

func jpegComponents(data []byte) int {
    if len(data)<4 || data[0]!=0xff || data[1]!=0xd8 { return 0 }
    i:=2
    for i<len(data) {
        for i<len(data)&&data[i]!=0xff { i++ }
        for i<len(data)&&data[i]==0xff { i++ }
        if i>=len(data) { return 0 }
        m:=data[i]; i++
        if m==0xd8||m==0xd9||(m>=0xd0&&m<=0xd7) { continue }
        if i+2>len(data) { return 0 }
        l:=int(data[i])<<8|int(data[i+1]); if l<2 || i+l>len(data) { return 0 }
        seg:=i+2
        if (m>=0xc0&&m<=0xc3)||(m>=0xc5&&m<=0xc7)||(m>=0xc9&&m<=0xcb)||(m>=0xcd&&m<=0xcf) { if seg+5<len(data){ return int(data[seg+5]) } }
        i += l
    }
    return 0
}

func verboseInfo(opt *options, dec *decoded, ow, oh int) {
    fmt.Fprintf(os.Stderr, "File: %s\n", dec.name)
    fmt.Fprintf(os.Stderr, "Source width: %d\n", dec.width)
    fmt.Fprintf(os.Stderr, "Source height: %d\n", dec.height)
    fmt.Fprintf(os.Stderr, "Source color components: %d\n", dec.comps)
    fmt.Fprintf(os.Stderr, "Output width: %d\n", ow)
    fmt.Fprintf(os.Stderr, "Output height: %d\n", oh)
    fmt.Fprintf(os.Stderr, "Output palette (%d chars): '%s'\n", len([]rune(opt.palette)), opt.palette)
    // A compact approximation of the original progress meter.
    fmt.Fprint(os.Stderr, "Decompressing image [########################################################]\r\n")
}

func renderOne(opt *options, img image.Image, ow, oh int, out io.Writer) {
    cells := make([][]cell, oh)
    for y:=0; y<oh; y++ { cells[y]=make([]cell, ow) }
    b:=img.Bounds(); sw,sh:=b.Dx(),b.Dy()
    pal:=[]rune(opt.palette)
    for y:=0;y<oh;y++{
        sy0, sy1 := span(y, oh, sh)
        for x:=0;x<ow;x++{
            sx0, sx1 := span(x, ow, sw)
            var sr,sg,sb float64; n:=0.0
            for yy:=sy0; yy<sy1; yy++ { for xx:=sx0; xx<sx1; xx++ { r,g,bb,_:=img.At(b.Min.X+xx,b.Min.Y+yy).RGBA(); sr+=float64(r>>8); sg+=float64(g>>8); sb+=float64(bb>>8); n++ } }
            if n==0 { n=1 }
            c:=cell{r:sr/n,g:sg/n,b:sb/n}
            c.lum = c.r*opt.red + c.g*opt.green + c.b*opt.blue
            lumForChar := c.lum
            if opt.invert { lumForChar = 255 - lumForChar }
            idx:=int(math.Round(lumForChar*float64(len(pal)-1)/255.0)); if idx<0{idx=0}; if idx>=len(pal){idx=len(pal)-1}
            c.ch=pal[idx]
            cells[y][x]=c
        }
    }
    if opt.flipY { for i,j:=0,oh-1; i<j; i,j=i+1,j-1 { cells[i],cells[j]=cells[j],cells[i] } }
    if opt.flipX { for y:=range cells { for i,j:=0,ow-1; i<j; i,j=i+1,j-1 { cells[y][i],cells[y][j]=cells[y][j],cells[y][i] } } }
    if opt.html { renderHTML(opt,cells,out); return }
    renderText(opt,cells,out)
}

func span(i, outN, inN int) (int,int) {
    if outN<=0 || inN<=0 { return 0,0 }
    a:=i*inN/outN; b:=(i+1)*inN/outN
    if b<=a { b=a+1 }
    if a<0 { a=0 }; if b>inN { b=inN }
    return a,b
}

func renderText(opt *options, cells [][]cell, out io.Writer) {
    h:=len(cells); w:=0; if h>0 { w=len(cells[0]) }
    if opt.border { fmt.Fprint(out,"+"); for i:=0;i<w;i++{fmt.Fprint(out,"-")}; fmt.Fprint(out,"+\n") }
    for _, row := range cells {
        if opt.border { fmt.Fprint(out,"|") }
        for _, c := range row { writeANSIChar(out,opt,c) }
        if opt.border { fmt.Fprint(out,"|") }
        fmt.Fprint(out,"\n")
    }
    if opt.border { fmt.Fprint(out,"+"); for i:=0;i<w;i++{fmt.Fprint(out,"-")}; fmt.Fprint(out,"+\n") }
}

func writeANSIChar(out io.Writer, opt *options, c cell) {
    if !(opt.colors || opt.grayscale) { fmt.Fprintf(out,"%c",c.ch); return }
    r,g,b := c.r,c.g,c.b
    lum := c.lum
    if opt.grayscale { r,g,b = lum,lum,lum }
    code,bold := ansiCode(r,g,b)
    if opt.fill { if code!=0 { fmt.Fprintf(out,"\033[%dm%c\033[0m", code+10, c.ch); return } } else { if code!=0 { if bold { fmt.Fprintf(out,"\033[1m%c\033[0m", c.ch) } else { fmt.Fprintf(out,"\033[%dm%c\033[0m", code, c.ch) }; return } }
    fmt.Fprintf(out,"%c",c.ch)
}

func ansiCode(r,g,b float64) (int,bool) {
    maxc:=math.Max(r,math.Max(g,b)); minc:=math.Min(r,math.Min(g,b))
    if maxc < 30 { return 37,false }
    if maxc-minc < 35 { if maxc>220 { return 37,true }; if maxc>180 { return 37,false }; return 0,false }
    rr:=r>100; gg:=g>100; bb:=b>100
    code:=30
    switch { case rr&&gg&&bb: code=37; case rr&&gg: code=33; case rr&&bb: code=35; case gg&&bb: code=36; case rr: code=31; case gg: code=32; case bb: code=34; default: code=30 }
    return code, maxc>200
}

func renderHTML(opt *options, cells [][]cell, out io.Writer) {
    if !opt.htmlRaw { htmlHeader(opt,out) }
    if opt.colors || opt.grayscale { renderHTMLColored(opt,cells,out) } else { renderHTMLPlain(opt,cells,out) }
    if !opt.htmlRaw { htmlFooter(out) }
}

func htmlHeader(opt *options, out io.Writer) {
    fmt.Fprint(out,"<?xml version='1.0' encoding='ISO-8859-1'?>\n")
    fmt.Fprint(out,"<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
    fmt.Fprint(out,"<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n<head>\n")
    fmt.Fprintf(out,"<title>%s</title>\n", opt.htmlTitle)
    fmt.Fprint(out,"<style type='text/css'>\nbody {\n")
    if opt.invert { fmt.Fprint(out,"   background-color: white;\n") } else { fmt.Fprint(out,"background-color: black;\n") }
    fmt.Fprint(out,"}\n.ascii {\n   font-family: Courier;\n")
    if !(opt.colors || opt.grayscale) { if opt.invert { fmt.Fprint(out,"   color: black;\n") } else { fmt.Fprint(out,"   color: white;\n") } }
    fmt.Fprintf(out,"   font-size:%dpt;\n", opt.htmlFontSize)
    if opt.htmlNoBold { fmt.Fprint(out,"   font-weight: normal;\n") } else { fmt.Fprint(out,"   font-weight: bold;\n") }
    fmt.Fprint(out,"}\n</style>\n</head>\n<body>\n<div class='ascii'><pre>\n")
}
func htmlFooter(out io.Writer) { fmt.Fprint(out,"</div>\n</body>\n</html>\n") }

func renderHTMLPlain(opt *options, cells [][]cell, out io.Writer) {
    h:=len(cells); w:=0; if h>0 { w=len(cells[0]) }
    if opt.border { fmt.Fprint(out,"+"); for i:=0;i<w;i++{fmt.Fprint(out,"-")}; fmt.Fprint(out,"+\n") }
    for _, row := range cells { if opt.border{fmt.Fprint(out,"|")}; for _,c:= range row { fmt.Fprintf(out,"%c",c.ch) }; if opt.border{fmt.Fprint(out,"|")}; fmt.Fprint(out,"\n") }
    if opt.border { fmt.Fprint(out,"+"); for i:=0;i<w;i++{fmt.Fprint(out,"-")}; fmt.Fprint(out,"+\n") }
    if !opt.htmlRaw { fmt.Fprint(out,"</pre>\n") }
}

func renderHTMLColored(opt *options, cells [][]cell, out io.Writer) {
    h:=len(cells); w:=0; if h>0 { w=len(cells[0]) }
    if opt.border { fmt.Fprint(out,"+"); for i:=0;i<w;i++{fmt.Fprint(out,"-")}; fmt.Fprint(out,"+\n") }
    for _, row := range cells {
        if opt.border { fmt.Fprint(out,"|") }
        for _, c := range row { writeHTMLSpan(out,opt,c) }
        if opt.border { fmt.Fprint(out,"|") }
        fmt.Fprint(out,"<br/>")
    }
    if opt.border { fmt.Fprint(out,"+"); for i:=0;i<w;i++{fmt.Fprint(out,"-")}; fmt.Fprint(out,"+") }
    if !opt.htmlRaw { fmt.Fprint(out,"</pre>\n") }
}

func writeHTMLSpan(out io.Writer, opt *options, c cell) {
    r,g,b := c.r,c.g,c.b
    if opt.grayscale { v:=c.lum; r,g,b=v,v,v }
    ri,gi,bi := clampByte(r),clampByte(g),clampByte(b)
    content := htmlChar(c.ch)
    if opt.fill { fr,fg,fb := halfByte(ri),halfByte(gi),halfByte(bi); fmt.Fprintf(out,"<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>%s</span>", fr,fg,fb,ri,gi,bi,content) } else { fmt.Fprintf(out,"<span style='color:#%02x%02x%02x;'>%s</span>", ri,gi,bi,content) }
}
func clampByte(v float64) int { if v<0{return 0}; if v>255{return 255}; return int(math.Round(v)) }
func halfByte(v int) int { if v<=0 { return 0 }; return (v-1)/2 }
func htmlChar(r rune) string { if r==' ' { return "&nbsp;" }; switch r { case '&': return "&amp;"; case '<': return "&lt;"; case '>': return "&gt;" }; return string(r) }
EOF
cat > compile.sh <<'EOF'
