set -euo pipefail
cd "$(dirname "$0")"
go build -trimpath -ldflags='-s -w' -o executable .
EOF
chmod +x compile.sh
cat > .gitignore <<'EOF'
/executable
*.o
*.a
*.so
*.dylib
*.dll
*.exe
*.test
*.out
core
core.*
